let r_attack = env.attack("burn em conta forjada sem verificacao de autenticidade", &ix_attack, &contas_attack);

if r_attack.program_result == ProgramResult::Success {
    let after_forged = after(&r_attack, &forged_ledger_key);
    let new_supply = read_u64(after_forged.data(), 40);
    let new_balance = read_u64(after_forged.data(), 48);
    env.effect(
        "conta forjada foi aceita e teve supply/balance sobrescritos sem verificacao de autenticidade",
        new_supply == 900 && new_balance == 400,
    );
}
